// 独立条件控制同意必要来源门：真实Interaction接口的有限组件，未登记完整World。
#include "resident/domains/family/legacy_control_consent.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;int checks=0;
// 保留首个失败，后续普通矩阵不在本组件运行。
void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}
// 同一Common角色与原会话节点，接受/撤回各自有不同的本人语义来源。
struct Fixture {
    std::shared_ptr<CommonCatalog> shared=std::make_shared<CommonCatalog>();CommonState seed;FamilyState family;InteractionCatalog interaction;InteractionState state;LegacyControlConsentCatalog catalog;
    Fixture(){
        seed.identity.world_id[0]=8;seed.identity.execution_epoch=2;seed.identity.revision=5;seed.identity.tick=20;seed.metadata.scenario_id="scene";seed.metadata.player_actor_id="former";seed.next_instance_id=9;
        shared->actor_ids={"former","next"};shared->places.insert("home",{"home","town",{}});RoleDefinition role;role.id="contact";role.initial_actor="next";role.place_id="home";shared->roles.insert(role.id,role);seed.roles.insert(role.id,{"next",true,{}});
        for(const auto* name:{"former","next"}){ActorRecord actor;actor.id=name;actor.alive=true;actor.available=true;actor.hp=100;actor.birth_tick=-20000;actor.location=SettlementLocation{"town","home"};seed.actors.insert(name,actor);}
        AdultAdoptionFact adopted;adopted.agreement.adopter_actor_id="former";adopted.agreement.adoptee_actor_id="next";adopted.agreement.accepted_tick=1;family.facts.insert("family:1",adopted);family.children.insert("next","family:1");seed.facts.insert("family:1",{"family:1","family_adult_adoption","family",{}});
        DialogueDefinition talk;talk.id="dialogue";talk.context_role="contact";talk.entry="yes";for(const auto* id:{"yes","withdraw","old_retirement"}){DialogueNode node;node.id=id;node.kind="say";node.speaker="$provider";talk.nodes.push_back(node);}interaction.dialogues.push_back(talk);interaction.common=shared;
        InteractionSession session;session.actor_id="former";session.id="interaction:2";session.dialogue_id="dialogue";session.node_id="yes";session.phase="say";session.context={"home","next","contact"};state.interactions.push_back(session);
        LegacyControlConsentDefinition d;d.id="conditional";d.predecessor_actor_id="former";d.successor_actor_id="next";d.dialogue_id="dialogue";d.accept_node_id="yes";d.revoke_node_id="withdraw";catalog.enabled=true;catalog.definitions.insert(d.id,d);
    }
};
}
// 接受和撤回只是纯报价；尚不写许可账、资产或玩家控制。
int main(){try{
    Fixture f;CommonStore common(f.seed,f.shared);InteractionAccess access;access.battle_occupied=[](const StableId&){return false;};access.resolve_location=[&](const StableId& id){return common.actor(id)->location;};access.role=[&](const StableId& id)->std::optional<RoleAssignmentView>{const auto* row=common.state().roles.find(id);if(!row)return {};return RoleAssignmentView{row->actor_id,row->enabled};};
    // 原候选可用确切人物ID或provider发言；玩家choice、空说话人和第三人均不能代签。
    for(const auto* speaker:{"$player","former","stranger",""}){auto bad=f.interaction;bad.dialogues.front().nodes.front().speaker=speaker;check(!validate_legacy_control_consent_catalog(f.catalog,*f.shared,bad).ok,"other speaker signed legacy consent");}
    {auto good=f.interaction;good.dialogues.front().nodes.front().speaker="next";check(validate_legacy_control_consent_catalog(f.catalog,*f.shared,good).ok,"exact successor speaker rejected");auto choice=good;choice.dialogues.front().nodes.front().kind="choice";check(!validate_legacy_control_consent_catalog(f.catalog,*f.shared,choice).ok,"player choice signed legacy consent");}
    auto quote=[&](const StableId& decision){return preview_legacy_control_decision(common,f.family,f.state,f.interaction,access,f.catalog,"former","next","conditional",decision);};
    check(validate_legacy_control_consent_catalog(f.catalog,*f.shared,f.interaction).ok,"new two-node catalog invalid");const auto before=encode_common_state(common.state());auto accepted=quote("accept");if(!accepted.ok)std::cerr<<accepted.error.original.code<<'\n';check(accepted.ok&&accepted.value.decision.decision=="accept"&&accepted.value.decision.relation_fact_id=="family:1","actual independent acceptance source missing");check(revalidate_legacy_control_decision(common,f.family,f.state,f.interaction,access,f.catalog,accepted.value).ok,"same exact current source refused");check(compare_boundary(before,encode_common_state(common.state())).exact(),"source quote changed control or state");
    check(!quote("revoke").ok,"accept node allowed candidate withdrawal");f.state.interactions.front().node_id="withdraw";auto revoked=quote("revoke");check(revoked.ok&&revoked.value.decision.node_id=="withdraw","real candidate withdrawal source missing");check(!revalidate_legacy_control_decision(common,f.family,f.state,f.interaction,access,f.catalog,accepted.value).ok,"old acceptance callback survived withdrawal node");
    auto corrupt=revoked.value.decision;corrupt.decision="accept";check(!validate_legacy_control_decision_source(common,f.family,*f.shared,f.interaction,f.catalog,corrupt).ok,"withdrawal snapshot reinterpreted as acceptance");f.state.interactions.front().node_id="old_retirement";check(!quote("accept").ok,"old retirement node silently granted new consent");f.state.interactions.front().node_id="yes";
    ++common.state().identity.execution_epoch;check(!revalidate_legacy_control_decision(common,f.family,f.state,f.interaction,access,f.catalog,accepted.value).ok,"old epoch source remained callable");--common.state().identity.execution_epoch;
    common.state().actors.find("former")->alive=false;check(!quote("accept").ok,"dead predecessor obtained fresh signature");common.state().actors.find("former")->alive=true;
    common.state().actors.find("next")->birth_tick=0;check(!quote("accept").ok,"minor signed conditional control consent");common.state().actors.find("next")->birth_tick=-20000;
    using namespace boundary;auto config=obj({{"profile",V{StableId{"authored_posthumous_control_consent_v1"}}},{"request_ids",string_array({"conditional"})}});auto definition=obj({{"id",V{StableId{"conditional"}}},{"predecessor_actor_id",V{StableId{"former"}}},{"successor_actor_id",V{StableId{"next"}}},{"dialogue_id",V{StableId{"dialogue"}}},{"accept_node_id",V{StableId{"yes"}}},{"revoke_node_id",V{StableId{"withdraw"}}},{"terms_version",V{Integer{1}}},{"consent_kind",V{StableId{"successor_accepts_control_after_death_v1"}}},{"scope",V{StableId{"own_life_control_only"}}}});auto defs=obj({{"conditional",definition}});check(decode_legacy_control_consent_catalog(config,defs).ok,"unique zero-asset author source invalid");auto old=config;*old.find("profile")=V{StableId{"authored_voluntary_succession_v1"}};check(!decode_legacy_control_consent_catalog(old,defs).ok,"old voluntary profile silently converted");auto expanded=defs;*expanded.find("conditional")->find("scope")=V{StableId{"player_control_and_selected_personal_assets"}};check(!decode_legacy_control_consent_catalog(config,expanded).ok,"asset authority smuggled into conditional control consent");expanded=defs;expanded.find("conditional")->as<V::Dict>()->emplace_back("scope",V{StableId{"anything"}});check(!decode_legacy_control_consent_catalog(config,expanded).ok,"duplicate nested author scope accepted");auto no_withdraw=f.catalog;no_withdraw.definitions.rows().front().second.revoke_node_id="yes";check(!validate_legacy_control_consent_catalog(no_withdraw,*f.shared,f.interaction).ok,"irrevocable same-node permission accepted");
    // 同一实际节点来源经两种永久边界往返，接受与撤回不互换。
    for(auto original:{accepted.value.decision,revoked.value.decision}){auto encoded=encode_legacy_control_decision_source(original);auto restored=decode_legacy_control_decision_source(encoded);check(restored.ok&&legacy_control_decision_equal(original,restored.value)&&compare_boundary(encoded,encode_legacy_control_decision_source(restored.value)).exact(),"conditional source JSON cold changed");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);check(visit_legacy_control_decision_source(writer,restored.value).ok&&writer.finish().ok,"conditional source typed write failed");const auto& input=bytes;CodecVisitor reader(input);LegacyControlDecisionSource cold;check(visit_legacy_control_decision_source(reader,cold).ok&&reader.finish().ok&&legacy_control_decision_equal(original,cold),"conditional source typed cold changed");}
    auto duplicate=encode_legacy_control_decision_source(accepted.value.decision);duplicate.as<V::Dict>()->emplace_back("decision",V{StableId{"revoke"}});check(!decode_legacy_control_decision_source(duplicate).ok,"duplicate saved decision accepted");duplicate=encode_legacy_control_decision_source(accepted.value.decision);duplicate.find("context")->as<V::Dict>()->emplace_back("provider_actor_id",V{StableId{"other"}});check(!decode_legacy_control_decision_source(duplicate).ok,"nested source provider duplicate accepted");auto malformed=accepted.value.decision;malformed.field_order={"unknown"};CodecVisitor::Buffer malformed_bytes;CodecVisitor malformed_writer(malformed_bytes);check(!visit_legacy_control_decision_source(malformed_writer,malformed).ok,"invalid saved source field order normalized");
    check(compare_boundary(before,encode_common_state(common.state())).exact(),"source checks wrote state or RNG");std::cout<<"LEGACY_CONTROL_CONSENT "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& error){std::cerr<<"LEGACY_CONTROL_CONSENT "<<checks<<" checks 1 failure: "<<error.what()<<'\n';return 1;}}
